import{_ as o,l as r,o as i,c as s,v as t,p as d,x as e,d as l,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"孤儿与 init","description":"","frontmatter":{"title":"孤儿与 init","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/orphan-init.md","filePath":"cs/orphan-init.md","lastUpdated":1789023840000}'),h={name:"cs/orphan-init.md"};function m(_,a,u,P,f,B){const n=r("Mermaid");return i(),s("div",null,[a[1]||(a[1]=t('<h1 id="孤儿与-init" tabindex="-1">孤儿与 init <a class="header-anchor" href="#孤儿与-init" aria-label="Permalink to &quot;孤儿与 init&quot;">​</a></h1><div class="epigraph"><p>父进程先退出时，子进程成为孤儿，必须过继给一个始终 wait 的祖先——传统上是 PID 1 的 init。</p><footer>—— 据 Tanenbaum and Bos, Modern Operating Systems；Silberschatz et al. 整理</footer></div><p><a href="/cs/wait-zombie">上一课</a>要求父收割僵尸。缺口是：父自己可以先 <code>exit</code>。若无人再 wait，孤儿结束会变成无人收的僵尸，PID 泄漏。Unix 的规则：把孤儿的父指针改到 <strong>init</strong>（或现代的子重器），由它循环 wait。本课只钉过继，不写 init 的全部用户态服务。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>进程树是 PCB 上的父子指针。父退出时，内核遍历其孩子：活着的改 <code>ppid</code>，已是僵尸的也改，以便新父能 wait 到。缺口不是新的退出码格式，而是保证<strong>系统里永远有一个愿意收尸的进程</strong>。PID 1 不能随便杀光：它挂了，内核通常 panic，因为过继目标没了。</p><p><span class="marginnote">有的系统让最近的「子重器」而不是全局 init 来收，避免 PID 1 成为瓶颈。语义仍是：孤儿必有新父，新父会 wait。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>exit</code> 路径：通知自己的父（可能把它从 wait 中唤醒），然后把孩子过继给 init。init 的用户代码循环 <code>wait</code>，把过继来的僵尸收光。会话与控制终端如何随父退出而断开，下一课进程组再收；本课只保证父指针合法。</p>',8)),(i(),d(p,null,{default:e(()=>[c(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E7%88%B6%E9%80%80%E5%87%BA%22%5D%20--%3E%20ORPH%5B%22%E5%AD%90%E6%88%90%E5%AD%A4%E5%84%BF%22%5D%0A%20%20ORPH%20--%3E%20INIT%5B%22%E8%BF%87%E7%BB%A7%E5%88%B0%20init%22%5D%0A%20%20INIT%20--%3E%20REAP%5B%22init%20wait%20%E6%94%B6%E5%83%B5%E5%B0%B8%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>fork 出的守护进程故意让父退出、自己过继，从而与终端脱钩——动机在进程组课，机制已在本课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>过继维持 wait 协议的不变量：每个僵尸都有一个活父。调度与地址空间不因此改变；变的只是 PCB 上的亲缘。与<a href="/cs/signals">信号</a>的交界：过继可能伴随 <code>SIGCHLD</code> 发给新父。init 必须对这条信号保持收割，不能忽略后永不 wait。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 systemd 的服务管理写成 OS 主干，不讨论 PID 1 在容器命名空间里是「容器内的 init」。内核线程一般挂在 kthreadd 下，不走用户 init 的 wait。杀 init 的后果是策略，课内只承认它特殊。</p><p>后课默认：每个用户进程最终能被谁 wait 到。退出时内核还要拆哪些资源、以什么顺序，下一课把 <code>exit</code> 与回收写全。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>孤儿过继给 init（或子重器），以免僵尸无人收。</li><li>PID 1 是 wait 协议的根。</li><li>退出路径上的资源释放顺序是下一课。</li><li>出处：Tanenbaum and Bos, <em>MOS</em>；Silberschatz et al., <em>OSC</em>。</li></ul>',8))])}const b=o(h,[["render",m]]);export{T as __pageData,b as default};
